import { cache } from 'react'

const POSTS_ENDPOINT = 'https://jsonplaceholder.typicode.com/posts'

export interface BlogPost {
  userId: number
  id: number
  title: string
  body: string
}

export interface BlogComment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function isBlogPost(value: unknown): value is BlogPost {
  return (
    isRecord(value) &&
    typeof value.userId === 'number' &&
    typeof value.id === 'number' &&
    typeof value.title === 'string' &&
    typeof value.body === 'string'
  )
}

function isBlogComment(value: unknown): value is BlogComment {
  return (
    isRecord(value) &&
    typeof value.postId === 'number' &&
    typeof value.id === 'number' &&
    typeof value.name === 'string' &&
    typeof value.email === 'string' &&
    typeof value.body === 'string'
  )
}

async function fetchJson(
  url: string,
  revalidate: number
): Promise<{ data: unknown; status: number }> {
  const response = await fetch(url, {
    next: { revalidate },
  })

  if (!response.ok && response.status !== 404) {
    throw new Error(`Blog API request failed with status ${response.status}`)
  }

  const data: unknown = await response.json()
  return { data, status: response.status }
}

export async function getBlogPosts(revalidate: number): Promise<BlogPost[]> {
  const { data } = await fetchJson(POSTS_ENDPOINT, revalidate)

  if (!Array.isArray(data) || !data.every(isBlogPost)) {
    throw new Error('Blog API returned an invalid posts response')
  }

  return data
}

export const getBlogPost = cache(
  async (id: string, revalidate: number): Promise<BlogPost | null> => {
    if (!/^\d+$/.test(id)) {
      return null
    }

    const { data, status } = await fetchJson(
      `${POSTS_ENDPOINT}/${encodeURIComponent(id)}`,
      revalidate
    )

    if (status === 404 || !isBlogPost(data)) {
      return null
    }

    return data
  }
)

export async function getBlogComments(
  id: string,
  revalidate: number
): Promise<BlogComment[]> {
  const { data } = await fetchJson(
    `${POSTS_ENDPOINT}/${encodeURIComponent(id)}/comments`,
    revalidate
  )

  if (!Array.isArray(data) || !data.every(isBlogComment)) {
    throw new Error('Blog API returned an invalid comments response')
  }

  return data
}
